package android.text.style;import android.graphics.*;import android.graphics.drawable.Drawable;public class ImageSpan extends ReplacementSpan {private final Drawable drawable;public ImageSpan(Drawable d){drawable=d;}public Drawable getDrawable(){return drawable;}public int getSize(Paint p,CharSequence t,int s,int e,Paint.FontMetricsInt fm){return drawable.getBounds().width();}public void draw(Canvas c,CharSequence t,int s,int e,float x,int top,int y,int bottom,Paint p){c.save();c.translate(x,bottom-drawable.getBounds().height());drawable.draw(c);c.restore();}}
